def semver_sort(versions):
    def parse(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is None:
            pre_ids = None
        else:
            ids = pre.split('.')
            pre_ids = []
            for ident in ids:
                if ident.isdigit():
                    pre_ids.append((0, int(ident)))
                else:
                    pre_ids.append((1, ident))
        return (major, minor, patch, pre_ids)

    def key(v):
        major, minor, patch, pre_ids = parse(v)
        has_pre = 0 if pre_ids is not None else 1
        pre_key = pre_ids if pre_ids is not None else []
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=key)

